public class BinaryRecordCodecTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static byte[] enc(PlayerStat stat) {
        try {
            byte[] data = BinaryRecordCodec.encode(stat);
            return data == null ? new byte[0] : data;
        } catch (Exception e) {
            System.out.println("FAIL  encode threw " + e.getClass().getSimpleName());
            failures++;
            return new byte[0];
        }
    }

    static PlayerStat dec(byte[] data) {
        try {
            return BinaryRecordCodec.decode(data);
        } catch (Exception e) {
            System.out.println("FAIL  decode threw " + e.getClass().getSimpleName());
            failures++;
            return null;
        }
    }

    public static void main(String[] args) {
        PlayerStat ada = new PlayerStat("Ada", 7, 12.5, true);
        byte[] adaBytes = enc(ada);
        check("encoded length for a 3-char name", 18, adaBytes.length);
        check("first two bytes are the UTF length", "[0, 3]",
                java.util.Arrays.toString(java.util.Arrays.copyOf(adaBytes, Math.min(2, adaBytes.length))));

        PlayerStat back = dec(adaBytes);
        check("name round trip", "Ada", back == null ? "<null>" : back.name());
        check("level round trip", 7, back == null ? -1 : back.level());
        check("score round trip", 12.5, back == null ? -1.0 : back.score());
        check("active round trip", true, back == null ? false : back.active());

        PlayerStat edge = new PlayerStat("", -3, 0.0, false);
        byte[] edgeBytes = enc(edge);
        check("encoded length for an empty name", 15, edgeBytes.length);
        PlayerStat edgeBack = dec(edgeBytes);
        check("empty name round trip", "", edgeBack == null ? "<null>" : edgeBack.name());
        check("negative level round trip", -3, edgeBack == null ? 0 : edgeBack.level());
        check("record equality after round trip", true, edge.equals(edgeBack));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

