import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.IOException;

record PlayerStat(String name, int level, double score, boolean active) { }

public class BinaryRecordCodec {

    public static byte[] encode(PlayerStat stat) throws IOException {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (DataOutputStream out = new DataOutputStream(bytes)) {
            out.writeUTF(stat.name());
            out.writeInt(stat.level());
            out.writeDouble(stat.score());
            out.writeBoolean(stat.active());
        }
        return bytes.toByteArray();
    }

    public static PlayerStat decode(byte[] data) throws IOException {
        try (DataInputStream in = new DataInputStream(new ByteArrayInputStream(data))) {
            String name = in.readUTF();
            int level = in.readInt();
            double score = in.readDouble();
            boolean active = in.readBoolean();
            return new PlayerStat(name, level, score, active);
        }
    }
}
